export function projectOwner190QaReconciliationRawSourceToParent(path,value){
 assert.equal(typeof path,'string');assert.ok(Buffer.isBuffer(value));
 if(!Object.hasOwn(rows,path))return value;
 const row=rows[path];let source=value;
 assert.equal(source.length,row.afterBytes,'OWNER190_QA_RECONCILIATION_CURRENT_RAW_BYTES');assert.equal(hash(source),row.afterSha256,'OWNER190_QA_RECONCILIATION_COMPLETE_CURRENT_RAW_SOURCE');
 for(const op of [...row.inverse].reverse()){
  const after=Buffer.from(op.afterBase64,'base64'),before=Buffer.from(op.beforeBase64,'base64');
  assert.equal(op.multiplicity,1,'OWNER190_QA_RECONCILIATION_REVIEWED_SPAN_MULTIPLICITY');
  assert.equal(source.indexOf(after),op.afterOffset,'OWNER190_QA_RECONCILIATION_EXACT_REVIEWED_RAW_SPAN_POSITION');
  assert.equal(source.indexOf(after,op.afterOffset+after.length),-1,'OWNER190_QA_RECONCILIATION_EXACT_REVIEWED_RAW_SPAN_UNIQUE');
  assert.deepEqual(source.subarray(op.afterOffset,op.afterOffset+after.length),after,'OWNER190_QA_RECONCILIATION_EXACT_REVIEWED_RAW_SPAN');
  source=Buffer.concat([source.subarray(0,op.afterOffset),before,source.subarray(op.afterOffset+after.length)]);
 }
 assert.equal(source.length,row.beforeBytes,'OWNER190_QA_RECONCILIATION_COMPLETE_HISTORICAL_PARENT_RAW_BYTES');assert.equal(hash(source),row.beforeSha256,'OWNER190_QA_RECONCILIATION_COMPLETE_HISTORICAL_PARENT_RAW_SHA');
 return source;
}
